face.layout_source:
// spectral-delay.face: the panel for tap/examples/spectral/spectral-delay.tap.
//
// Only layout lives here.  The style is a theme from face/themes, chosen per
// family in face/themes/families.json:
//
//   facec face/themes/<theme>.face tap/examples/spectral/spectral-delay.face --meta <graph>.cragmeta

face "Spectral Delay" {
  row(gap = 10) {
    box "Time" { knob "Low" (low_time) knob "Mid" (mid_time) knob "High" (high_time) }
    box "Bands" { knob "Low/Mid" (low_split) knob "Mid/High" (high_split) }
    box "Echo" { knob.big "Feedback" (feedback) }
    box "Mix" { vslider "Wet" (wet_level) vslider "Dry" (dry_level) }
    viz(grow = 1)
  }
}
